create or replace TABLE KFL_PRODUCTION.DBP_ODS.ODS_BON_KOPF cluster by (
     MANDANT_ID,
     BON_DAT,
     WUP_ID 
)(
	BON_ID VARCHAR(25) NOT NULL COMMENT 'Eindeutige ID eines Bons, generierter Hashwert.',
	BON_DAT DATE NOT NULL COMMENT 'Checkoutdatum, auch Businessday bzw. Kassenkey.',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH - ein Mandant pro Land.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Marktnummer, wird nicht gegen den Marktstamm geprüft.',
	KASSE_TYP_ID NUMBER(38,0) COMMENT 'Kassentyp. Folgende Typen kommen vor: 1 = default (Sales POS), 2 = Info, 3 = Leergut (Empties), 4 = Server (Back-Office), 5 = Imbiss, 6 = Mobile, 7 = Emergency, 8 = SCO (SelfCheckOut),  -1 = unbekannt.',
	KUNDENKARTE_TYP_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'ID zum Kundenkartentyp mit Werten 0, 1, 2. ',
	BON_NR NUMBER(38,0) NOT NULL COMMENT 'Die Bonnummer des Bons (ist eine fortlaufende Nummer die in der Kasse generiert wird, im Normalfall ist diese Nummer pro Tag und Kasse unique).',
	KASSE_NR NUMBER(38,0) NOT NULL COMMENT 'Nummer der Kasse.',
	KASSIERER_NR VARCHAR(4) WITH MASKING POLICY #unknown_policy COMMENT 'Nummer des Kassierers.',
	KUNDE_FG NUMBER(38,0) NOT NULL COMMENT 'Gibt an, ob dieser Bon für die Kundenzählung relevant ist. 1 = ja, 0 = nein.',
	BON_BEGINN TIMESTAMP_NTZ(9) COMMENT 'Start-Zeitpunkt des Bons.',
	BON_ENDE TIMESTAMP_NTZ(9) COMMENT 'Ende-Zeitpunkt des Bons.',
	UMSATZ_MWST NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Auf den Mehrwertsteueranteil entfallender Betrag.',
	UMSATZ_BRUTTO NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Umsatz Brutto Betrag.',
	BON_BOOKING TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Buchungszeitpunkt des Bons, relevant z.Bsp. für artbew. Kann vom Bondatum abweichen, z.Bsp. wenn eine Kasse offline war.',
	DAT_BOOKING DATE NOT NULL COMMENT 'Buchungsdatum des Bons, relevant z.Bsp. für artbew. Kann vom Bondatum abweichen, z.Bsp. wenn eine Kasse offline war. Redundant zu bon_booking aus Performancegründen.',
	TURNOVER_FG NUMBER(38,0) NOT NULL COMMENT 'Flag kennzeichnet die Umsatzrelevanz des Bons. 1 = relevant.',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR.',
	REACTIVATED_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'SPALTE WIRD NICHT BEFÜLLT / FUNKTIONIERT NICHT. Bons können zurückgestellt und später reaktiviert werden (= 1), wenn z.Bsp. der Kunde nicht gleich zahlen kann. Diese Bons verbleiben länger im System und die Zeiten dürfen nicht in die Berechnungen eingehen.',
	PERSONAL_ID VARCHAR(25) COMMENT 'Personalnummer (nur bei Personalrabatt) als Hashwert verfremdet (Compress).',
	BETRAG_PERSONAL_RABATT NUMBER(18,4) COMMENT 'Mitarbeiterrabatt als Geldbetrag.',
	KPOS_KASSE_TYP VARCHAR(10) COMMENT 'Im Kassensystem KPOS verwendete nicht-numerische Kassentypen.',
	WAGEN_NR NUMBER(38,0) COMMENT 'Nummer des Einkaufswagens.',
	KUNDENKARTE_ID VARCHAR(255) COMMENT 'Beinhaltet die gehashte Kundennummer.',
	DRUECKEN_SUMMENTASTE TIMESTAMP_NTZ(9) COMMENT 'Zeitstempel wird erzeugt wenn die Summentaste an der Kasse gedrückt wird; Zeitstempel wird nur einmalig erzeugt.',
	SCHLIESSEN_KASSENSCHUBLADE TIMESTAMP_NTZ(9) COMMENT 'Zeitstempel wird an der Kasse erzeugt, wenn die Kassenlade geschlossen wird.',
	FISKALISIERUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Kennzeichnung für einen Bon, ob dieser für Fiskalisierung relevant ist.',
	BON_NR_FISCAL NUMBER(38,0) COMMENT 'In Kombination mit Kasse und Markt einmalig kombiniertes Feld (Fiscal invoice receipt).',
	ALTERNATIVE_KARTE_ID VARCHAR(255) COMMENT 'Beinhaltet gehashte kundenkartennummer, außer KCARD ( Z.B:TCBO, Payback).Es können in einigen Ländern beide Kartentyp gleichzeitig, Kaufland Card und eine andere, an der Kasse gezeigt werden, in welchem Fall dann die KL-Card Kundennummer in Spalte kundenkarte_id geschrieben wird und in dieser Spalte die Nummer der anderen Karte.',
	SUSPENDED_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag: Kennzeichnung des Suspended-Status der Transaktion. 1 = suspended',
	SUSPENDED_BON_NR NUMBER(38,0) COMMENT 'Bonnummer des zuvor zurückgestellten Bons. Ein reaktivierter Bon erhält eine neue Bonnummer und mit dieser Spalte kann auf den vorher zurückgestellten Bon verwiesen werden.\n            Bons können zurückgestellt und später reaktiviert werden, wenn z.Bsp. der Kunde nicht gleich zahlen kann. Diese Bons verbleiben länger im Kassensystem und die Zeiten dürfen nicht in die Berechnungen eingehen.',
	ONLINE_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Kennzeichnet einen Online Bon; Fg = 1 = Online Bon liegt vor; Fg = 0 = Offline Bon liegt vor. Sobald eine Bonzeile ein Online-Verkauf ist, zählt der Bon als Online. Quelle Kassen XML aztec Code Stelle 2 E-Food / Offline mit umgekehrter Flag Logik.',
	ONLINE_TRANSAKTION_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Transaktionsnummer, einzigartig innerhalbt eines Bons. Tritt nur bei Online Bestellungen auf. Quelle: Kassen XML Aztec Code Stelle 5 TransactionID.',
	ONLINE_BESTELLUNG_NR VARCHAR(100) NOT NULL DEFAULT '0' COMMENT 'Bestellnummer bei Online Bestellungen, alphanumerisch mit unterschiedlicher Länge. Quelle: Kassen XML Aztec Code Stelle 7 Ordernumber.',
	DIENSTLEISTER_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Bei Online Bestellungen wird ein Dienstleister beauftragt die bestellte Ware zusammen zu stellen. ID kann 0 bis 9 annehmen. Siehe Lookup Tabelle l_dienstleister und dienstleister_spr_zu. Quelle Kassen XML Aztec Code Stelle 4 VendorID.',
	GERAET_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Gerätekennzeichnung mit dem die online bestellte Ware gescannt wurde. < 200 Waage; >200 und < 800 Geschenkkorb (MDE); > 800 MDE E-Food RO. Quelle Kassen XML Aztec Code Stelle 6 DeviceID.',
	BON_TYP_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Kennzeichnet den Typ des Bons: 0 = rein gedruckter Bon; 1 = gedruckter Bon mit Sendung an Web Service; 2 = reiner Digitalbon. Quelle: Kassen XML digitalReceipt.',
	BON_GEDRUCKT_FG NUMBER(38,0) NOT NULL COMMENT 'Gibt an, ob der Bon ausgedruckt wurde. 1 = Bon ausgedruckt; 0 = Bon nicht ausgedruckt. Default = 1 (in ETL definiert). Quelle ./paperReceiptPrintout',
	BONDRUCK_ABGELEHNT_FG NUMBER(38,0) NOT NULL COMMENT 'Gibt an, ob der Kunde \"an der Kasse\" auf Nachfrage den Bondruck abgelehnt hat. 1 = ja(abgelehnt); 0 = nein (nicht abgelehnt). Default = -1 (für Altdaten. in ETL definiert). Quelle ./customerSuppressedReceipt. \n            Ist beim Kunde im CRM / K Card \"kein Druck des Bons\" hinterlegt hat, erhält diese Spalte trotzdem 0 (false). In diesem Fall wäre sowohl bon_abgelehnt_fg, als auch bon_gedruckt_fg gleich 0. Bei Self Checkout Kassen gilt der Bondruck als automatisch abgelehnt, wenn der Kunde innerhalb von 5 Sekunden nicht den Audruck auswählt.',
	KUNDENKARTE_STATUS_BEZ VARCHAR(20) COMMENT 'Gibt den Status der Kundenkarte an, den die Kasse vom CRM in der Schnittstelle erhält. Quelle ../loyaltyCardPositions/state\n            SUCCESSFUL -> Request & Response an CRM technisch erfolgreich, Karte ohne Fehler vom CRM gemeldet -> CRM Promotions angewendet/gegeben\n            PENDING -> Randfall technisch: Request läuft jedoch keine Response bis zum Transaktions-Abschluss (oder Bon Abbruch cellation oder Hard-Reset) -> keine CRM Promotion angewendet\n            INITIALIZED -> Randfall technisch: Request initialisiert aber Kasse wird während der Transaktion heruntergefahren oder Transaktion aus einem anderen Grund systemseitig automatisch abgebrochen -> keine CRM Promotion angewendet (ist ohnehin keine reguläre SALES Transaktion)\n            FAILED -> abhängig vom gemeldeten errorcode, ob CRM Promotion gewährt wird\n            TIMEDOUT -> abhängig vom gemeldeten errorcode, ob CRM Promotion gewährt wird',
	KUNDENKARTE_FEHLER_TXT VARCHAR(50) COMMENT 'Errorcode der Kundenkarte, den die Kasse vom CRM in der Schnittstelle erhält. Quelle ../loyaltyCardPositions/errorcode\n            ERROR_ARVADO_INTERNAL (arvato state: true)                -> no CRM BBYs, only common BBYs\n            ERROR_ARVADO_UNSUPPORTED(arvato state: true)      -> no CRM BBYs, only common BBYs\n            ERROR_CARD_NOT_ACTIVATED(arvato state: true)          -> no CRM BBYs, only common BBYs\n            ERROR_CARD_UNKNOWN(arvato state: true)                    -> no CRM BBYs, only common BBYs\n            ERROR_INTERNAL(arvato state: false)                                    -> common BBYs + CRM customer BBYs granted\n            ERROR_INVALID_RESPONSE(arvato state: false)                -> common BBYs + CRM customer BBYs granted\n            ERROR_IO(arvato state: false)                                                   -> common BBYs + CRM customer BBYs granted\n            \"NULL\"                                                                                                -> all promotions are granted',
	LOYALTY_BERECHTIGT_FG NUMBER(38,0) COMMENT 'Gibt an, ob CRM Promotion gewährt wurde. 1 = ja; 0 = nein. Ob eine Promotion aufgrund der CRM-Karte gewährt wird, hängt sowohl vom kundenkarte_status_bez als auch vom kundenkarte_fehler_txt ab, den die Kasse vom CRM in der Schnittstelle erhält.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	BON_ID_ORIG VARCHAR(25) COMMENT 'Bon-ID des Ursprungeinakufs bei Retouren.',
	BON_DAT_ORIG DATE COMMENT 'Datum des Ursprungseinkaufs bei Retouren.',
	WUP_ID_ORIG NUMBER(38,0) COMMENT 'Martknummer des Urpsrungeinkaufs bei Retouren.',
	KASSE_NR_ORIG NUMBER(38,0) COMMENT 'Nummer der Kasse des Ursprungskauf bei Retouren.',
	KUNDENKARTE_PROGRAMM_CD VARCHAR(10) COMMENT 'Gibt den Kundenbindungsprogramm der Karte wieder.',
	constraint PK_ODS_BON_KOPF primary key (BON_ID, BON_DAT, WUP_ID, MANDANT_ID)
)COMMENT='ODS - Aus den Kassensystemen near Realtime geladene Bon-Köpfe'
;